mapper.select:
SELECT id, stream_id, owner_type, owner_id, scope, content, status,
       source_session_id, source_request_id, write_origin, create_time, update_time
FROM ai_agent_ltm_curated_entry
WHERE owner_type = #{ownerType}
  AND owner_id = #{ownerId}
  AND scope = #{scope}
  AND deleted = 0
  AND status = 'ACTIVE'
ORDER BY id ASC
